import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const c=JSON.parse('{"title":"厨师求职信（教材写作模板）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/17-chef-job-application-template.md","filePath":"zh/more/maltese/practice/emails/17-chef-job-application-template.md"}'),e={name:"zh/more/maltese/practice/emails/17-chef-job-application-template.md"},o=r('<h1 id="厨师求职信-教材写作模板" tabindex="-1">厨师求职信（教材写作模板） <a class="header-anchor" href="#厨师求职信-教材写作模板" aria-label="Permalink to &quot;厨师求职信（教材写作模板）&quot;">​</a></h1><p><strong>场景：</strong> 申请人给餐厅写信申请厨师职位。这是 PDF 中的教材原文模板，括号内为填空选项。注意：原文落款印刷为 <code>Tisjiet</code>，规范正式拼写为 <code>Tislijiet</code>。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a><strong>Mingħand（发件人 From）：</strong> gorg.com.mt <strong>Data（日期）：</strong> 16 ta&#39; Ottubru 2026 <strong>Suġġett（主题）：</strong> Applikazzjoni ta&#39; xogħol ta&#39; kok</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a><strong>Mingħand:</strong> gorg.com.mt <strong>Data:</strong> 16 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; kok</p><p>Għażiż Sinjur / Sinjura</p><p>Jien qiegħed nibgħatlek din l-ittra biex (napplika / tapplika) għal xogħol.</p><p>Nispera li tinsab tajjeb. Qed nibgħatlek din l-ittra elettronika sabiex napplika għal xogħol ta&#39; kok fir-restorant tiegħek.</p><p>Jien nixtieq naħdem bħala kok għax inħobb insajjar, inħobb naħdem ma&#39; ħaddieħor u nħobb niltaqa&#39; man-nies.</p><p>Kont immur l-iskola tal-ITS (institute of tourism studies) u minn hemm ġibt iċ-ċertifikati li kelli bżonn. Għandi esperjenza ta&#39; ħames snin naħdem f&#39;restorant ta&#39; lukanda lussuża.</p><p>u għalhekk naħseb li kapaċi għal dan ix-xogħol. Naf nitkellem Ingliż, Malti, u ftit Taljan.</p><p>Grazzi talli qrajt din l-ittra. Napprezza jekk tikkunsidrani għal dan ix-xogħol.</p><p>Nista&#39; niltaqa&#39; miegħek biex nikkellmu iktar fid-dettall kuljum mit-8 ta&#39; filgħodu sas-7 ta&#39; filgħaxija. / meta tkun komdu inti.</p><p>Tisjiet, John Mallia</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a></p><p><strong>整句：</strong> 收件人（To）：info@restorant.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a></td><td>邮箱地址</td><td>餐厅的招聘邮箱（示例）</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: gorg.com.mt</p><p><strong>整句：</strong> 发件人（From）：gorg.com.mt</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签</td></tr><tr><td>gorg.com.mt</td><td>邮箱地址</td><td>发件人示例邮箱（Gorg）</td></tr></tbody></table><p><strong>Malti:</strong> Data: 16 ta&#39; Ottubru 2026</p><p><strong>整句：</strong> 日期：2026 年 10 月 16 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;</td></tr><tr><td>16</td><td>十六</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ottubru</td><td>十月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; kok</p><p><strong>整句：</strong> 主题：厨师职位申请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Applikazzjoni</td><td>申请</td><td>阴性名词，借词 application</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>xogħol</td><td>工作；职位</td><td>阳性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>kok</td><td>厨师</td><td>借词 cook</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura</p><p><strong>整句：</strong> 亲爱的先生 / 女士</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għażiż</td><td>亲爱的</td><td>阳性单数形容词</td></tr><tr><td>Sinjur</td><td>先生</td><td>阳性名词</td></tr><tr><td>/</td><td>或</td><td>二选一</td></tr><tr><td>Sinjura</td><td>女士</td><td>阴性名词</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Jien qiegħed nibgħatlek din l-ittra biex (napplika / tapplika) għal xogħol.</p><p><strong>整句：</strong> 我写这封信是为了（申请 / 你申请）工作。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jien</td><td>我</td><td>第一人称代词</td></tr><tr><td>qiegħed</td><td>正在</td><td>进行时标记（阳性）</td></tr><tr><td>nibgħatlek</td><td>我发给你</td><td><code>nibgħat</code>+<code>-lek</code></td></tr><tr><td>din l-ittra</td><td>这封信</td><td>din（这）+ittra（信）</td></tr><tr><td>biex</td><td>为了</td><td>目的连词</td></tr><tr><td>napplika</td><td>我申请</td><td>选项①：借词 apply 第一人称</td></tr><tr><td>tapplika</td><td>你申请</td><td>选项②：第二人称</td></tr><tr><td>għal xogħol</td><td>为了工作</td><td>għal（为了）+xogħol（工作）</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li tinsab tajjeb. Qed nibgħatlek din l-ittra elettronika sabiex napplika għal xogħol ta&#39; kok fir-restorant tiegħek.</p><p><strong>整句：</strong> 希望你安好。我发这封邮件是为了申请您餐厅的厨师职位。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数</td></tr><tr><td>li</td><td>引出从句</td><td>连词</td></tr><tr><td>tinsab</td><td>你处于</td><td>第二人称</td></tr><tr><td>tajjeb</td><td>好</td><td>副词/形容词</td></tr><tr><td>Qed</td><td>正在</td><td>进行时标记</td></tr><tr><td>nibgħatlek</td><td>我发给你</td><td>见上</td></tr><tr><td>din l-ittra elettronika</td><td>这封电子邮件</td><td>ittra+elettronika</td></tr><tr><td>sabiex</td><td>为了</td><td>书面连词</td></tr><tr><td>napplika</td><td>我申请</td><td>第一人称</td></tr><tr><td>għal xogħol ta&#39; kok</td><td>应聘厨师工作</td><td>kok（厨师，借词 cook）</td></tr><tr><td>fir-restorant</td><td>在餐厅</td><td><code>f&#39;</code>+<code>ir-restorant</code></td></tr><tr><td>tiegħek</td><td>你的</td><td>阳性所有格</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Jien nixtieq naħdem bħala kok għax inħobb insajjar, inħobb naħdem ma&#39; ħaddieħor u nħobb niltaqa&#39; man-nies.</p><p><strong>整句：</strong> 我想当厨师，因为我喜欢做饭、喜欢和别人一起工作、喜欢和人打交道。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jien</td><td>我</td><td>代词</td></tr><tr><td>nixtieq</td><td>我想要</td><td>第一人称单数</td></tr><tr><td>naħdem</td><td>我工作</td><td>第一人称单数</td></tr><tr><td>bħala</td><td>作为</td><td>介词</td></tr><tr><td>kok</td><td>厨师</td><td>借词 cook</td></tr><tr><td>għax</td><td>因为</td><td>原因连词</td></tr><tr><td>inħobb</td><td>我喜欢</td><td>第一人称单数</td></tr><tr><td>insajjar</td><td>我做饭</td><td>第一人称单数</td></tr><tr><td>ma&#39; ħaddieħor</td><td>和其他人</td><td>ħaddieħor（别人）</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>niltaqa&#39;</td><td>我见面；打交道</td><td>第一人称单数</td></tr><tr><td>man-nies</td><td>和人</td><td><code>ma&#39;</code>+<code>in-nies</code>（人们）</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Kont immur l-iskola tal-ITS (institute of tourism studies) u minn hemm ġibt iċ-ċertifikati li kelli bżonn.</p><p><strong>整句：</strong> 我上过 ITS（旅游学院），从那里拿到了我需要的证书。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Kont</td><td>我曾经</td><td>过去时助动词</td></tr><tr><td>immur</td><td>我去</td><td>第一人称单数</td></tr><tr><td>l-iskola</td><td>学校</td><td>阴性名词，带定冠词</td></tr><tr><td>tal-ITS</td><td>ITS 的</td><td><code>ta&#39;</code>+<code>l-ITS</code>（旅游学院）</td></tr><tr><td>minn hemm</td><td>从那里</td><td>地点短语</td></tr><tr><td>ġibt</td><td>我拿到；我带来</td><td>第一人称单数过去时</td></tr><tr><td>iċ-ċertifikati</td><td>证书</td><td><code>ċertifikat</code> 复数，带定冠词</td></tr><tr><td>li</td><td>那些</td><td>关系代词</td></tr><tr><td>kelli bżonn</td><td>我需要</td><td><code>kell</code>（有）+<code>bżonn</code>（需要）</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi esperjenza ta&#39; ħames snin naħdem f&#39;restorant ta&#39; lukanda lussuża.</p><p><strong>整句：</strong> 我有五年在豪华酒店餐厅工作的经验。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandi</td><td>我有</td><td><code>għand</code> 第一人称</td></tr><tr><td>esperjenza</td><td>经验</td><td>阴性名词</td></tr><tr><td>ta&#39; ħames snin</td><td>五年的</td><td>ħames（五）+snin（年）</td></tr><tr><td>naħdem</td><td>我工作</td><td>第一人称单数</td></tr><tr><td>f&#39;restorant</td><td>在餐厅</td><td><code>f&#39;</code>+restorant</td></tr><tr><td>ta&#39; lukanda</td><td>酒店的</td><td>lukanda（酒店）</td></tr><tr><td>lussuża</td><td>豪华的</td><td>阴性形容词</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> u għalhekk naħseb li kapaċi għal dan ix-xogħol. Naf nitkellem Ingliż, Malti, u ftit Taljan.</p><p><strong>整句：</strong> 因此我认为我能胜任这份工作。我会说英语、马耳他语和一点意大利语。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>għalhekk</td><td>因此</td><td><code>għal</code>+<code>hekk</code></td></tr><tr><td>naħseb</td><td>我认为</td><td>第一人称单数</td></tr><tr><td>li</td><td>引出从句</td><td>连词</td></tr><tr><td>kapaċi</td><td>有能力的</td><td>借词 capable</td></tr><tr><td>għal dan ix-xogħol</td><td>胜任这份工作</td><td>dan（这）+xogħol（工作）</td></tr><tr><td>Naf</td><td>我会；我知道</td><td>第一人称单数</td></tr><tr><td>nitkellem</td><td>我说话</td><td>第一人称单数</td></tr><tr><td>Ingliż</td><td>英语</td><td>语言名</td></tr><tr><td>Malti</td><td>马耳他语</td><td>语言名</td></tr><tr><td>ftit</td><td>一点</td><td>数量词</td></tr><tr><td>Taljan</td><td>意大利语</td><td>语言名</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi talli qrajt din l-ittra. Napprezza jekk tikkunsidrani għal dan ix-xogħol.</p><p><strong>整句：</strong> 谢谢您读这封信。如果您考虑我应聘这份工作，我将很感激。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr><tr><td>talli</td><td>因为（您）……</td><td>书面原因表达</td></tr><tr><td>qrajt</td><td>您读了</td><td><code>qara</code> 第二人称单数过去时</td></tr><tr><td>din l-ittra</td><td>这封信</td><td>见上</td></tr><tr><td>Napprezza</td><td>我感激</td><td>借词 appreciate</td></tr><tr><td>jekk</td><td>如果</td><td>条件连词</td></tr><tr><td>tikkunsidrani</td><td>您考虑我</td><td><code>tikkunsidra</code>+<code>-ni</code></td></tr><tr><td>għal dan ix-xogħol</td><td>应聘这份工作</td><td>见上</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; niltaqa&#39; miegħek biex nikkellmu iktar fid-dettall kuljum mit-8 ta&#39; filgħodu sas-7 ta&#39; filgħaxija. / meta tkun komdu inti.</p><p><strong>整句：</strong> 我可以每天上午 8 点到晚上 7 点和您见面详谈。/ 或者您方便的时候。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>我能</td><td>第一人称单数</td></tr><tr><td>niltaqa&#39;</td><td>我见面</td><td>第一人称单数</td></tr><tr><td>miegħek</td><td>和您</td><td><code>ma&#39;</code>+<code>-ek</code></td></tr><tr><td>biex</td><td>为了</td><td>目的连词</td></tr><tr><td>nikkellmu</td><td>我们谈</td><td><code>kellem</code> 第一人称复数</td></tr><tr><td>iktar</td><td>更多；更</td><td>比较级副词</td></tr><tr><td>fid-dettall</td><td>详细地</td><td><code>f&#39;</code>+<code>id-dettall</code>（细节）</td></tr><tr><td>kuljum</td><td>每天</td><td>副词</td></tr><tr><td>mit-8 ta&#39; filgħodu</td><td>从上午 8 点</td><td><code>minn</code>+<code>it-8</code></td></tr><tr><td>sas-7 ta&#39; filgħaxija</td><td>到晚上 7 点</td><td><code>sa</code>+<code>is-7</code></td></tr><tr><td>meta</td><td>当……时</td><td>时间连词</td></tr><tr><td>tkun komdu</td><td>您方便</td><td>tkun（是）+komdu（舒适/方便）</td></tr><tr><td>inti</td><td>您</td><td>第二人称代词</td></tr></tbody></table><h3 id="_10" tabindex="-1">10. <a class="header-anchor" href="#_10" aria-label="Permalink to &quot;10.&quot;">​</a></h3><p><strong>Malti:</strong> Tisjiet,</p><p><strong>整句：</strong> 此致敬意</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tisjiet</td><td>此致敬意</td><td>原文印刷如此；按教材正式结尾表，标准拼写应为 <strong>Tislijiet</strong></td></tr></tbody></table><p><strong>Malti:</strong> John Mallia</p><p><strong>整句：</strong> John Mallia（署名示例）</p>',61),i=[o];function n(l,s,h,g,p,b){return d(),a("div",null,i)}const m=t(e,[["render",n]]);export{c as __pageData,m as default};
